package com.mhtextractor.app;

import com.mhtextractor.util.SelectionState;

import java.util.List;
import java.util.function.Predicate;

/**
 * 列表复选框三态 / Shift 区间多选的规则入口（P3-3b-12）：{@code gui} 对 {@code util.SelectionState}
 * 的全部静态调用经本类 1:1 收口 —— 三态枚举与四静态方法的参数顺序、返回语义与底层完全一致
 * （只搬不改，枚举间双向映射），gui 层不再直连 {@code util.SelectionState}。
 *
 * <p>本类<b>零 JavaFX、零 I18n</b>，属 {@code app} 层。</p>
 */
public final class SelectionRules {

    private SelectionRules() {
    }

    /** 三态：全部选中 / 部分选中 / 全部未选 —— 常量名与顺序和 {@link SelectionState.TriState} 一一对应 */
    public enum TriState {
        ALL, SOME, NONE
    }

    /**
     * 由已选数量与有效项总数计算三态：1:1 转发 {@link SelectionState#computeState}。
     *
     * @param selected 已选中数量
     * @param total    有效项总数
     * @return 总数或已选数为 0 时返回 {@link TriState#NONE}；已选数达到总数时返回
     * {@link TriState#ALL}；其余返回 {@link TriState#SOME}
     */
    public static TriState computeState(int selected, int total) {
        return toRules(SelectionState.computeState(selected, total));
    }

    /**
     * 列头 CheckBox 点击后的目标勾选值：当前全不选 → 全选（true）；全选或半选 → 全不选（false）。
     * 1:1 转发 {@link SelectionState#computeToggleTarget}（null 原样透传，与底层一致）。
     */
    public static boolean computeToggleTarget(TriState state) {
        return SelectionState.computeToggleTarget(toUnderlying(state));
    }

    /**
     * Shift 区间多选：按显示序取锚点行到当前行之间的全部行（含两端）。
     * 1:1 转发 {@link SelectionState#shiftSelectRange}（不涉及枚举映射）。
     */
    public static List<Object> shiftSelectRange(List<?> order, Object anchor, Object current) {
        return SelectionState.shiftSelectRange(order, anchor, current);
    }

    /**
     * Shift 区间反选判定：区间内全部行"已完全勾选"时返回 true。
     * 1:1 转发 {@link SelectionState#rangeAllChecked}（不涉及枚举映射）。
     */
    public static boolean rangeAllChecked(List<?> range, Predicate<Object> isChecked) {
        return SelectionState.rangeAllChecked(range, isChecked);
    }

    private static TriState toRules(SelectionState.TriState state) {
        if (state == null) {
            return null;
        }
        return switch (state) {
            case ALL -> TriState.ALL;
            case SOME -> TriState.SOME;
            case NONE -> TriState.NONE;
        };
    }

    private static SelectionState.TriState toUnderlying(TriState state) {
        if (state == null) {
            return null;
        }
        return switch (state) {
            case ALL -> SelectionState.TriState.ALL;
            case SOME -> SelectionState.TriState.SOME;
            case NONE -> SelectionState.TriState.NONE;
        };
    }
}
package com.mhtextractor.app;

import com.mhtextractor.util.ThumbnailPixels;

import java.nio.IntBuffer;

/**
 * 缩略图像素打包与尺寸校验纯函数（P3-3b-8）：{@code gui.util.ThumbnailFxBridge} 对
 * {@code util.ThumbnailPixels} 的两处纯静态调用经本类 1:1 收口 —— 参数顺序与返回语义
 * 与底层完全一致（只搬不改），gui 层不再直连 {@code util} 包。
 *
 * <p>像素契约（ARGB 非预乘、行优先连续、stride == width）由底层 {@link ThumbnailPixels}
 * 定义，本类不复制、不改写。</p>
 *
 * <p>本类<b>零 JavaFX、零 I18n</b>，属 {@code app} 层。</p>
 */
public final class PreviewPixelService {

    private PreviewPixelService() {
    }

    /**
     * 尺寸合法性（供调用方在构造 {@code WritableImage} 前做前置校验）：
     * 1:1 转发 {@link ThumbnailPixels#isUsable(int[], int, int)}。
     */
    public static boolean isUsable(int[] pixels, int width, int height) {
        return ThumbnailPixels.isUsable(pixels, width, height);
    }

    /**
     * 把 {@code IntBuffer}（position=0、limit=width*height）转成 int 数组：
     * 1:1 转发 {@link ThumbnailPixels#pack}；输入为 null 或尺寸非法时返回 null（表示"无法加载"）。
     */
    public static int[] pack(IntBuffer buffer, int width, int height) {
        return ThumbnailPixels.pack(buffer, width, height);
    }
}
package com.mhtextractor.util;

import java.nio.IntBuffer;

/**
 * 缩略图像素打包/解包（会话 18 · E1.4）。
 *
 * <p><b>为什么独立成类</b>：E1.4 把缩略图从"JavaFX {@code Image} 对象"改为"纯像素数组"，
 * 于是渲染层需要把像素数组解包回 {@code WritableImage}。这段打包/解包逻辑是<b>最容易悄悄写错</b>
 * 的地方（stride 填错会让图像斜切/错位），而它此前只能靠真实 GUI 预览才发现。
 * 抽成纯 Java 类后可以<b>零 JavaFX 单测</b>直接锁定 round-trip 正确性。</p>
 *
 * <p>约定：像素为 {@code ARGB}（非预乘）int，行优先连续存放，每行 {@code width} 个元素
 * （即 stride == width）。</p>
 */
public final class ThumbnailPixels {

    private ThumbnailPixels() {
    }

    /**
     * 把 {@code IntBuffer}（position=0、limit=width*height）转成 int 数组。
     *
     * @return 数组；输入为 null 或尺寸非法时返回 null（表示"无法加载"）
     */
    public static int[] pack(IntBuffer buffer, int width, int height) {
        if (buffer == null || width <= 0 || height <= 0) {
            return null;
        }
        int n = width * height;
        if (buffer.remaining() < n) {
            return null;
        }
        int[] out = new int[n];
        buffer.get(out, 0, n);
        return out;
    }

    /**
     * 把 int 数组拷入 {@code IntBuffer}（用于 JavaFX {@code PixelWriter.setPixels} 的
     * {@code PixelBuffer} 形态）。
     *
     * @return true = 拷入成功；false = 参数非法（尺寸不匹配/空数组）
     */
    public static boolean unpack(int[] pixels, IntBuffer target, int width, int height) {
        if (pixels == null || target == null || width <= 0 || height <= 0) {
            return false;
        }
        int n = width * height;
        if (pixels.length < n || target.remaining() < n) {
            return false;
        }
        target.put(pixels, 0, n);
        return true;
    }

    /** 尺寸合法性（供调用方在构造 {@code WritableImage} 前做前置校验） */
    public static boolean isUsable(int[] pixels, int width, int height) {
        if (pixels == null || width <= 0 || height <= 0) {
            return false;
        }
        return pixels.length >= width * height;
    }
}

